parameters.text:
=Review the following test cases against the user story and acceptance criteria provided.

Input (User Story / AC and Test Cases):
{{ $json.chatInput }}

parameters.jsCode:
const review = $input.item.json.output;
const issues = review.issues || [];

let md = `**Overall Verdict:** ${review.overallVerdict}\n\n**Summary:** ${review.summary}\n\n`;

if (issues.length === 0) {
  md += `No issues found.\n`;
} else {
  md += `**Review Comments:**\n`;
  for (const i of issues) {
    md += `- [${i.id}] (${i.relatedTestCaseId} | ${i.dimension} / ${i.severity}) ${i.comment}\n`;
  }
}

return [{
  json: {
    output: md,
    overallVerdict: review.overallVerdict,
    summary: review.summary,
    issues
  }
}];
